export function renderReactPersistentPreview(s,esc){const r=s.review,d=s.durability;const notice='Compatibility storage is Mulow’s project-scoped server SQLite, not browser localStorage. Stop retains saved data; source Revert does not roll back this database.';const recovery=s.recovery?'<button data-action="react-persistent-download">Download recovery snapshot</button>':'';if(s.status==='displaying')return `<section class="static-source-preview preview-running react-persistent-preview" data-interactive="true"><header><div><strong>App preview · saved project data</strong><small>${esc(notice)}</small></div><button data-action="react-persistent-stop">Stop preview</button></header><div class="persistent-save-status" role="status">${esc(({loading:'Loading the reviewed app; cache is preloaded before mounting.',saved:'Stored data writes acknowledged by the local server.',pending:'Saving project data… Latest changes are not yet durable.',unconfirmed:'Write outcome unconfirmed. Keep the recovery snapshot; no automatic retry.',failed:'The app or data operation failed. Stored data was not reset.',not_dispatched:'This edit was not sent because the workspace changed before dispatch. Keep a recovery copy; no retry was made. Stop and explicitly run again to load saved data.',committed_after_check:'The checked write committed. Stop and review again before further edits.'})[d?.state]||'Data status unconfirmed.')}${d?.state==='unconfirmed'?'<button data-action="react-persistent-check">Check write outcome</button>':''}${recovery}</div><iframe data-react-persistent-frame title="Reviewed app with project-scoped persistence" sandbox="allow-scripts" referrerpolicy="no-referrer" src="${esc(s.grant.frameUrl)}"></iframe></section>`;
 return `<section class="static-source-preview preview-review-card persistent-review-compact"><div class="preview-panel-content"><header><h2>Preview</h2></header>${s.message?'<p role="status">'+esc(s.message)+'</p>':['checking','starting'].includes(s.status)?'<p>'+esc(s.status==='checking'?'Checking this app. Nothing is running.':'Opening the reviewed app…')+'</p>':''}${!r?'<p>'+esc(notice)+'</p>':''}${r?'<p>Run this unverified app with project data saved on the Mulow server, not browser localStorage.</p><p>Stop keeps saved data. Source Revert does not undo data changes. App code may hang this tab.</p>':''}${r?.compatibilityReview?'<p><strong>Reviewed runtime update required.</strong> Your source, storage keys and saved data stay unchanged. This does not migrate or reset your data.</p>':''}${s.recovery?.pending?'<p class="persistent-recovery-warning">Some recent cache edits are not saved. Download a recovery copy if needed before loading saved data again.</p>':''}${r?'<details data-preview-disclosure="persistent-limits" data-preview-binding="'+esc(r.sessionId+':'+r.reviewId)+'"><summary>Details and limits</summary><p>Run authorizes project-data writes and the reviewed browser runtime'+(r.compatibilityReview?', including this exact compatibility update':'')+'. Original source is unchanged. The adapter replaces storage, events, clock, identifiers, confirmation and bounded timers. No network, Node, deployment or Goal verification.</p><p>Up to 32 declared keys, 64 KiB per JSON value and 256 KiB cache; 1 MiB data plus mutation receipts. SQLite overhead is additional. Five-minute grant, 32 timers (60 seconds each), five confirmation dialogs. Recovery covers the latest received cache, not all unsaved form fields.</p><p>Declared keys: '+esc(r.storageKeys.join(', '))+'</p><p>Reviewed source '+esc(r.binding.sourceRevision)+'</p><p>Compiled output '+esc(r.outputDigest)+'</p></details>':''}<footer class="preview-panel-actions">${s.status==='review'?'<button class="preview-primary" data-action="react-persistent-start">'+(r?.compatibilityReview?'Update runtime &amp; run':'Run preview')+'</button>':['checking','starting'].includes(s.status)?'':'<button data-action="react-persistent-review">Review preview</button>'}${s.pendingUnknown?'<button data-action="react-persistent-check">Check write outcome</button>':''}${s.durability?.state==='committed_after_check'?'<p>The checked write committed. Other cache edits may still be unsaved.</p>':''}${recovery}<button data-action="react-persistent-back">Back</button></footer></div></section>`;}
